Keyword.upsert_all([
  {id: 1, name: "Personaggio", description: "Generale dell'Armata\r\nOgni armata viene guidata in battaglia da almeno un Personaggio; il Generale dell’Armata è il Personaggio\r\npiù costoso (includendo artefatti, costi addizionali, etc.) nell’armata. In caso di costi uguali, sta al giocatore\r\nscegliere quale di questi personaggi sia il Generale. Il Generale dell’Armata deve essere annotato come\r\ncombattente numero 1 nella Lista d’armata.\r\nTipologia di personaggi\r\nI personaggi sono suddivisi in:\r\n●​ Personaggi Guerrieri Puri: personaggi senza potere o spirale di fede;\r\n●​ Personaggi Mistici Puri: personaggi con potere o spirale di fede, ma senza le abilità\r\nGuerriero-Mago o Monaco-Guerriero;\r\n●​ Personaggi Guerrieri Maghi: personaggi con potere e con abilità Guerriero-Mago;\r\n●​ Personaggi Monaci-Guerrieri: personaggi con spirale di fede e con abilità Monaco-Guerriero.\r\n\r\nI Personaggi, anche se esse non sono riportate nel loro profilo, dispongono di alcune abilità intrinseche al\r\nloro status di prescelti nel disegno divino:\r\n●​ Tutti i Personaggi dispongono di Artefatto/Rango.\r\n\r\nLe abilità dovute allo Status di Personaggio cumulano i loro effetti con quelle che il personaggio ottiene\r\nnuovamente. Pertanto un Personaggio che ottenga Sequenza di Colpi/1, all’effettivo ha Sequenza di Colpi/2\r\ndovuta allo status più Sequenza di Colpi/1 che ha ottenuto, per un totale di Sequenza di Colpi/3.\r\nPersonaggi Guerrieri - Sangue Divino\r\n", created_at: "2025-12-29T15:58:58Z", updated_at: "2025-12-30T18:34:25Z"},
  {id: 2, name: "Tiratore", description: nil, created_at: "2025-12-30T08:35:23Z", updated_at: "2025-12-31T10:34:19Z"},
  {id: 3, name: "Guerriero", description: "●​ I Personaggi Guerrieri Puri, Guerrieri-Maghi e Monaci-Guerrieri dispongono di:\r\n-​ Sequenza di Colpi/2;\r\n-​ Contrattacco;\r\n-​ Colpo da maestro/0;\r\n-​ Ricarica rapida, se dispongono di un valore di tiro;\r\n\r\nOgni Personaggio Guerriero, Guerriero-Mago o Monaco-Guerriero dispone di 1 ferita in più rispetto a quanto\r\nla sua Taglia prevede. Non beneficiano di questo bonus combattenti che ottengono lo status di personaggio\r\ndurante lo svolgimento di una partita.", created_at: "2025-12-30T08:36:37Z", updated_at: "2025-12-30T18:34:36Z"},
  {id: 4, name: "Mistico", description: "●​ I Personaggi Maghi Puri dispongono di:\r\n-​ Sequenza di Colpi/1;\r\n-​ Maestria degli Arcani;\r\n\r\n●​ I Personaggi Fedeli Puri dispongono di:\r\n-​ Sequenza di Colpi/1\r\n-​ Pietà/2.", created_at: "2025-12-30T08:49:41Z", updated_at: "2025-12-30T18:32:43Z"},
  {id: 5, name: "Mago", description: "●​ I Personaggi Maghi Puri dispongono di:\r\n-​ Sequenza di Colpi/1;\r\n-​ Maestria degli Arcani;", created_at: "2025-12-30T08:50:15Z", updated_at: "2025-12-30T18:33:36Z"},
  {id: 6, name: "Fedele", description: "●​ I Personaggi Fedeli Puri dispongono di:\r\n-​ Sequenza di Colpi/1\r\n-​ Pietà/2.", created_at: "2025-12-30T08:50:58Z", updated_at: "2025-12-30T18:32:56Z"},
  {id: 9, name: "Artiglieria Leggera Perforante", description: "Tiri di Artiglieria\r\nQuesta categoria include tutti i combattenti il cui rango include “Artiglieria Leggera” o “Artiglieria Pesante”.\r\n\r\nIl Tiro Perforante\r\nAl momento di procedere al tiro di Artiglieria Perforante, il combattente sceglie un bersaglio per il tiro (quindi visibile o a portata di Consapevolezza). Egli traccia una linea retta che, partendo dal centro della sua base e attraversando il suo arco di visuale, attraversa la base del bersaglio e rientra nella gittata scelta, perforando solo entro il limite della gittata.\r\nPer ogni combattente la cui base è attraversata, anche parzialmente, da questa linea, si effettui un test di tiro con difficoltà pari a quella della gittata entro cui si trova il combattente.\r\nSi applichino al tiro i normali modificatori dovuti alla taglia ed alla copertura (questo test di tiro può essere effettuato anche se non si vedono questi combattenti.) Un combattente non visibile è in copertura. ​\r\n​\r\nOgni combattente così colpito subisce un tiro per ferire la cui forza è pari a:\r\n●​ Artiglieria Leggera: forza piena sul primo bersaglio colpito e dimezzata (eccesso) su quelli seguenti;\r\n\r\nIl tiro si ferma e non prosegue sui bersagli seguenti se:\r\n●​ La linea attraversa un qualunque elemento scenico o congegno immobile senza punti struttura;\r\n●​ Un combattente colpito subisce un tiro per ferire che non causa ferite. Il tiro prosegue però normalmente se un combattente evita il tiro per ferire grazie ad una prova di Istinto di \r\nSopravvivenza.\r\nI combattenti dotati dell’abilità Esploratore e ancora nascosti non possono essere colpiti dai proiettili di Artiglieria Perforante.\r\nL’artiglieria perforante non randomizza in mischia. Il proiettile passa dritto per dritto.", created_at: "2025-12-30T19:22:36Z", updated_at: "2025-12-30T19:25:07Z"},
  {id: 10, name: "Artiglieria Pesante Perforante", description: "Tiri di Artiglieria\r\nQuesta categoria include tutti i combattenti il cui rango include “Artiglieria Leggera” o “Artiglieria Pesante”.\r\n\r\nIl Tiro Perforante\r\nAl momento di procedere al tiro di Artiglieria Perforante, il combattente sceglie un bersaglio per il tiro (quindi visibile o a portata di Consapevolezza). Egli traccia una linea retta che, partendo dal centro della sua base e attraversando il suo arco di visuale, attraversa la base del bersaglio e rientra nella gittata scelta, perforando solo entro il limite della gittata.\r\nPer ogni combattente la cui base è attraversata, anche parzialmente, da questa linea, si effettui un test di tiro con difficoltà pari a quella della gittata entro cui si trova il combattente.\r\nSi applichino al tiro i normali modificatori dovuti alla taglia ed alla copertura (questo test di tiro può essere effettuato anche se non si vedono questi combattenti.) Un combattente non visibile è in copertura. ​\r\n​\r\nOgni combattente così colpito subisce un tiro per ferire la cui forza è pari a:\r\n●​ Artiglieria Pesante: forza piena su tutti.\r\n\r\nIl tiro si ferma e non prosegue sui bersagli seguenti se:\r\n●​ La linea attraversa un qualunque elemento scenico o congegno immobile senza punti struttura;\r\n●​ Un combattente colpito subisce un tiro per ferire che non causa ferite. Il tiro prosegue però normalmente se un combattente evita il tiro per ferire grazie ad una prova di Istinto di \r\nSopravvivenza.\r\nI combattenti dotati dell’abilità Esploratore e ancora nascosti non possono essere colpiti dai proiettili di Artiglieria Perforante.\r\nL’artiglieria perforante non randomizza in mischia. Il proiettile passa dritto per dritto.", created_at: "2025-12-30T19:25:26Z", updated_at: "2025-12-30T19:25:26Z"},
  {id: 11, name: "PG Tiratore", description: "●​ I Personaggi Guerrieri Puri, Guerrieri-Maghi e Monaci-Guerrieri dispongono di:\r\n-​ Ricarica rapida, se dispongono di un valore di tiro;", created_at: "2025-12-31T10:35:07Z", updated_at: "2025-12-31T10:35:07Z"},
  {id: 12, name: "Alfiere", description: nil, created_at: "2025-12-31T10:58:52Z", updated_at: "2025-12-31T10:58:52Z"},
  {id: 13, name: "Musico", description: nil, created_at: "2025-12-31T10:59:23Z", updated_at: "2025-12-31T10:59:23Z"},
  {id: 14, name: "Porta Stendardo", description: nil, created_at: "2025-12-31T10:59:52Z", updated_at: "2025-12-31T10:59:52Z"},
  {id: 15, name: "Marchio della Ferocia", description: "Tutti i Wolfen e i Divoratori di taglia grande dotati di Comando/X sulla loro carta di riferimento beneficiano,\r\noltre ai normali vantaggi del comando, di questa capacità.\r\nPrima di ogni tiro di tattica essi generano un segnalino definito Marchio della Ferocia. Questo segnalino può\r\nessere assegnato ad un wolfen alleato che soddisfi tutte queste limitazioni:\r\n●​ è di rango pari o inferiore al loro (solo inferiore se è un altro Personaggio);\r\n●​ ha PAU pari o inferiore alla loro (solo inferiore se è un altro Personaggio);\r\n●​ è a portata del loro Comando.\r\nChi dispone di un Marchio della Ferocia ottiene Furia Guerriera finché dispone del marchio. Se già dispone\r\ndi Furia Guerriera ottiene un Marchio della Ferocia, egli può ricorrere alla Furia Guerriera dopo aver\r\neffettuato le sue prove di INI. Il segnalino è scartato a fine turno.", created_at: "2025-12-31T11:01:28Z", updated_at: "2025-12-31T11:01:28Z"},
  {id: 16, name: "Aura di Tenebre", description: "I combattenti dotati di Non-morto e Comando/X non beneficiano dei normali effetti dell’abilità e non possono\r\nformare uno Stato Maggiore. In contropartita essi forniscono un bonus in PAU pari al loro rango a tutti i loro\r\nalleati, dotati di Non-morto, di rango pari o inferiore, che si trovano a portata del loro Comando/X. Il valore di\r\nPAU di un combattente non può però, grazie al bonus, divenire maggiore di quello del combattente che\r\nfornisce il bonus.", created_at: "2025-12-31T11:01:46Z", updated_at: "2025-12-31T11:01:46Z"}
])
Equipment.upsert_all([
  {id: 1, name: "Spada-Ascia", description: "Se il portatore di una Spada Ascia infligge almeno 3 ferite con un tiro per ferire, allora egli causa 1 ferita in più.", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
  {id: 2, name: "Arma Sacra", description: "Una ferita eccezionale è un tiro per ferire in cui due dadi usati per determinare locazione e forza del colpo mostrano lo stesso risultato. A meno di indicazioni esplicitamente contrarie, un’Arma Sacra è sempre e solo un’Arma da Corpo a Corpo. Quando il portatore di un Arma Sacra ottiene una ferita eccezionale con un tiro per ferire effettuato con quest’arma, quel tiro per ferire causa 2 ferite in più. Quando il portatore di un’Armatura Sacra subisce una ferita eccezionale, quel tiro per ferire causa 2 ferite in meno, con un minimo di 0. Gli effetti di Arma e Armatura Sacra si annullano a vicenda, quindi il tiro per ferire si risolve normalmente. ​ Gli effetti degli equipaggiamenti sacri si applicano dopo aver calcolato il numero di ferite che verrebbero inflitte dal tiro per ferire. Per cui il minimo di ferite inflitte da un 6-6 ad un combattente con armatura sacra è 1 (il minimo per 6-6 sono 3 ferite, che poi diventano 1 per gli effetti dell’equipaggiamento), mentre il minimo di ferite inflitte da un 6-6 fatto da un combattente con arma sacra è 5 (il minimo per 6-6 sono 3 ferite, che poi diventano 5 per gli effetti di arma sacra).", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
  {id: 3, name: "Armatura Sacra", description: "Un ferita eccezionale è un tiro per ferire in cui due dadi usati per determinare locazione e forza del colpo mostrano lo stesso risultato. A meno di indicazioni esplicitamente contrarie, un’Arma Sacra è sempre e solo un’Arma da Corpo a Corpo. Quando il portatore di un Arma Sacra ottiene una ferita eccezionale con un tiro per ferire effettuato con quest’arma, quel tiro per ferire causa 2 ferite in più. Quando il portatore di un’Armatura Sacra subisce una ferita eccezionale, quel tiro per ferire causa 2 ferite in meno, con un minimo di 0. Gli effetti di Arma e Armatura Sacra si annullano a vicenda, quindi il tiro per ferire si risolve normalmente. ​ Gli effetti degli equipaggiamenti sacri si applicano dopo aver calcolato il numero di ferite che verrebbero inflitte dal tiro per ferire. Per cui il minimo di ferite inflitte da un 6-6 ad un combattente con armatura sacra è 1 (il minimo per 6-6 sono 3 ferite, che poi diventano 1 per gli effetti dell’equipaggiamento), mentre il minimo di ferite inflitte da un 6-6 fatto da un combattente con arma sacra è 5 (il minimo per 6-6 sono 3 ferite, che poi diventano 5 per gli effetti di arma sacra).", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
  {id: 4, name: "Arma Simbiotica", description: "Il portatore di un’arma simbiotica può, una volta per turno, decidere di risolvere un tiro per ferire considerando il proprio valore di Forza ed il valore di Resistenza nemico pari a 0. Il portatore di un’armatura simbiotica può, una volta per turno, decidere di risolvere un tiro per ferire che sta subendo considerando il valore di Forza nemico ed il proprio valore di Resistenza pari a 0. Abilità come Ossoduro, Flagello o il bonus dato da Fanatismo si applicano normalmente.", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
  {id: 5, name: "Armatura Simbiotica", description: "Il portatore di un’arma simbiotica può, una volta per turno, decidere di risolvere un tiro per ferire considerando il proprio valore di Forza ed il valore di Resistenza nemico pari a 0. Il portatore di un’armatura simbiotica può, una volta per turno, decidere di risolvere un tiro per ferire che sta subendo considerando il valore di Forza nemico ed il proprio valore di Resistenza pari a 0. Abilità come Ossoduro, Flagello o il bonus dato da Fanatismo si applicano normalmente.", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
  {id: 6, name: "Arma Eliante", description: "I portatori di questi equipaggiamenti possono essere bersaglio di alcuni effetti di gioco loro dedicati.", cost: 0, created_at: "2025-12-28T15:28:38Z", updated_at: "2025-12-28T15:28:38Z"},
