Army.upsert_all([
  {id: 1, name: "Divoratori di Vile-Tis", description: "Un giorno una Meteora cadde nella foresta di Caer Laen e da quella strana pietra emerse un Dio ferito e carico di odio per le altre divinità: la Bestia. La Bestia incontrò Ellis, un grande capo wolfen, e gli rivelò la verità sull'origine sua e dei suoi fratelli Wolfen; gli svelò il piano della dea Yllia, divinità in realtà maligna, che odiava i suoi figli e che era pronta a sacrificarli tutti nello scontro finale del Ragnarock. Sconvolto ma rafforzato da una nuova consapevolezza, Ellis ha unito sotto un'unica bandiera tutti coloro che cercano vendetta contro gli Dei e contro Yllia e marcia in cerca di vendetta.", path_id: 2, created_at: "2025-12-27T17:04:53Z", updated_at: "2025-12-27T17:04:53Z"}
])
